                                break ;

                default :
                                psf->error = SFE_BAD_OPEN_MODE ;
                                return -1 ;
                                break ;
                } ;

        if (mode == 0)
                psf->file.filedes = open (pathname, oflag) ;
        else
                psf->file.filedes = open (pathname, oflag, mode) ;

